def statuses():
    yield 'queued'
    yield 'running'
    yield 'done'
for status in statuses():
    print(status)

def squares(limit):
    for number in range(1, limit + 1):
        yield number * number
print(list(squares(4)))

def positive(values):
    for value in values:
        if value > 0:
            yield value
print(list(positive([-2, 0, 3, 5])))

def all_tags(groups):
    for group in groups:
        yield from group
print(list(all_tags([['new', 'paid'], ['packed']])))
